    --bg-darker: #0a0e13;
    --surface: #1a2332;
    --surface-light: #242e3f;
    --text-primary: #e8ecf1;
    --text-secondary: #a8b0ba;
    --accent: #58a6ff;
    --accent-hover: #79c0ff;
    --focus-ring: #58a6ff;
    --border: #30363d;
    --success: #3fb950;
    --error: #f85149;
}

@media (prefers-color-scheme: light) {
    :root {
        --bg-dark: #ffffff;
        --bg-darker: #f6f8fa;
        --surface: #f6f8fa;
        --surface-light: #eaeef2;
        --text-primary: #24292f;
        --text-secondary: #57606a;
        --accent: #0969da;
        --accent-hover: #0860ca;
        --focus-ring: #0969da;
        --border: #d0d7de;
        --success: #1a7f0f;
        --error: #cf222e;
    }
}

body {
    background-color: var(--bg-dark);
    color: var(--text-primary);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial,
        sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji';
    font-size: 16px;
    line-height: 1.5;
    min-height: 100vh;
    padding: 20px;
}

main {
    max-width: 600px;
    margin: 0 auto;
}

.quiz-container {
    background-color: var(--bg-darker);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 40px 32px;
}

h1 {
    font-size: 28px;
    font-weight: 600;
    margin-bottom: 12px;
}

.intro {
    color: var(--text-secondary);
    margin-bottom: 32px;
    font-size: 14px;
}

.form-field {
    margin-bottom: 32px;
}

.form-field:last-of-type {
    margin-bottom: 24px;
}

fieldset {
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 20px;
    background-color: var(--surface);
}

legend {
    font-weight: 600;
    font-size: 16px;
    padding: 0 8px;
    margin: -8px 0 16px -8px;
    color: var(--text-primary);
}

.checkbox-wrapper {
    display: flex;
    align-items: center;
    margin-bottom: 12px;
}

.checkbox-wrapper:last-child {
    margin-bottom: 0;
}

input[type="checkbox"] {
    width: 20px;
    height: 20px;
    margin-right: 12px;
    cursor: pointer;
    accent-color: var(--accent);
    flex-shrink: 0;
    /* Ensure focus ring is visible */
    outline: 2px solid transparent;
    outline-offset: 2px;
}

input[type="checkbox"]:focus {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
}

input[type="checkbox"]:focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
}

label {
    cursor: pointer;
    color: var(--text-primary);
    display: flex;
    align-items: center;
    font-size: 15px;
}

label:hover input[type="checkbox"] {
    opacity: 0.8;
}

.help-text {
    font-size: 13px;
    color: var(--text-secondary);
    margin-top: 8px;
    margin-bottom: 12px;
}

.error-text {
    font-size: 13px;
    color: var(--error);
    margin-top: 12px;
}

.submit-btn {
    width: 100%;
    padding: 12px 16px;
    background-color: var(--accent);
    color: #ffffff;
    border: none;
    border-radius: 6px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 150ms ease-in-out;
}

.submit-btn:hover {
    background-color: var(--accent-hover);
}

.submit-btn:focus {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
}

.submit-btn:focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
}

.submit-btn:active {
    background-color: var(--accent);
}

.results-container {
    background-color: var(--surface-light);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 24px;
    margin-top: 32px;
}

.results-container h2 {
    font-size: 20px;
    font-weight: 600;
    margin-bottom: 16px;
}

#results-message {
    margin-bottom: 20px;
    line-height: 1.6;
}

.retry-btn {
    padding: 10px 16px;
    background-color: var(--surface);
    color: var(--accent);
    border: 1px solid var(--accent);
    border-radius: 6px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 150ms ease-in-out;
}

.retry-btn:hover {
    background-color: var(--accent);
    color: #ffffff;
}

.retry-btn:focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
}

/* Responsive */
@media (max-width: 480px) {
    .quiz-container {
        padding: 24px 16px;
    }

    h1 {
        font-size: 24px;
    }

    fieldset {
        padding: 16px;
    }

    legend {
        margin: -6px 0 12px -6px;
    }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}
