const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

async function runAxeTest() {
    const htmlPath = path.join(__dirname, 'index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

    const browser = await chromium.launch();
    const page = await browser.newPage();
    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Inject axe-core
    const axePath = require.resolve('axe-core/axe.min.js');
    await page.addScriptTag({ path: axePath });

    // Run axe
    const results = await page.evaluate(() => window.axe.run());
    await browser.close();

    // Separate WCAG from best-practice violations
    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    const report = {
        wcag: wcag.map(v => ({
            id: v.id,
            impact: v.impact,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        })),
        bp: bp.map(v => ({
            id: v.id,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        }))
    };

    console.log(JSON.stringify(report, null, 2));
    process.exit(wcag.length > 0 ? 1 : 0);
}

runAxeTest().catch(err => {
    console.error('Test error:', err.message);
    process.exit(1);
});

